import 'dart:io';

import 'package:zyra/data/onboarding_bank_contract.dart';

void main(List<String> args) {
  final values = onboardingBankExpectedSqlValues();
  final suite =
      '''-- OA-ZYRA-196: the server question bank must exactly mirror the Dart bank.
-- Generated by: dart run tool/generate_onboarding_bank_sql_values.dart --write-suite
-- Run in the Supabase SQL editor. Green means the transaction rolls back
-- without an exception; any one-sided bank edit raises with its delta.

BEGIN;

DO \$suite\$
DECLARE
  v_delta jsonb;
BEGIN
  WITH expected(qid, variant, ch4_scored, show_if_qid, show_if_not_any_of) AS (
    VALUES
-- BEGIN DART-GENERATED BANK
$values
-- END DART-GENERATED BANK
  ),
  actual AS (
    SELECT
      COALESCE(row_json->>'qid', row_json->>'question_id') AS qid,
      CASE lower(COALESCE(
        row_json->>'variant',
        row_json->>'gender_visibility',
        row_json->>'gender',
        'all'
      ))
        WHEN 'male' THEN 'menOnly'
        WHEN 'men' THEN 'menOnly'
        WHEN 'menonly' THEN 'menOnly'
        WHEN 'female' THEN 'womenOnly'
        WHEN 'women' THEN 'womenOnly'
        WHEN 'womenonly' THEN 'womenOnly'
        ELSE 'all'
      END AS variant,
      COALESCE((row_json->>'ch4_scored')::boolean, false) AS ch4_scored,
      NULLIF(row_json->>'show_if_qid', '') AS show_if_qid,
      COALESCE(
        NULLIF(row_json->'show_if_not_any_of', 'null'::jsonb),
        '[]'::jsonb
      ) AS show_if_not_any_of
    FROM (
      SELECT to_jsonb(question_row) AS row_json
      FROM public.zyra_onboarding_questions AS question_row
    ) AS bank
  ),
  delta AS (
    (SELECT 'missing_on_server' AS side, expected.* FROM expected
      EXCEPT
     SELECT 'missing_on_server' AS side, actual.* FROM actual)
    UNION ALL
    (SELECT 'missing_in_dart' AS side, actual.* FROM actual
      EXCEPT
     SELECT 'missing_in_dart' AS side, expected.* FROM expected)
  )
  SELECT jsonb_agg(to_jsonb(delta) ORDER BY qid, variant, side)
  INTO v_delta
  FROM delta;

  IF v_delta IS NOT NULL THEN
    RAISE EXCEPTION 'OA-ZYRA-196 onboarding bank drift: %', v_delta;
  END IF;
END
\$suite\$;

ROLLBACK;
''';

  if (args.contains('--write-suite')) {
    File(
      'supabase/tests/zyra_onboarding_bank_suite.sql',
    ).writeAsStringSync(suite);
    return;
  }
  stdout.write(values);
}
